static inline void h2_release_mbuf(struct h2c *h2c)
{
	struct buffer *buf;
	unsigned int count = 0;

	while (b_size(buf = br_head_pick(h2c->mbuf))) {
		b_free(buf);
		count++;
	}

	h2c->flags &= ~(H2_CF_MUX_MFULL | H2_CF_DEM_MROOM);

